"""Write the three goal-based Linux user guides using recorded native captures."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2]
NAMES=['connect','empty','cards','sign','format','stamp','pin','progress','success','failure','verify','certificate','invalid','untrusted','unsigned','format','documents','details','history','settings','settings','background','about','menu']
